+import React, { useEffect, useState } from 'react';
+
+import { _t } from '../../../../languageHandler';
+import AccessibleButton from '../../elements/AccessibleButton';
+import Field from '../../elements/Field';
+import Spinner from '../../elements/Spinner';
+import Heading from '../../typography/Heading';
+import { DeviceWithVerification } from './types';
+
+interface Props {
+    device: DeviceWithVerification;
+    saveDeviceName: (deviceId: string, deviceName: string) => Promise<void>;
+}
+
+export const DeviceDetailHeading: React.FC<Props> = ({ device, saveDeviceName }) => {
+    const [displayName, setDisplayName] = useState(device.display_name);
+    const [editedName, setEditedName] = useState('');
+    const [isEditing, setIsEditing] = useState(false);
+    const [isSaving, setIsSaving] = useState(false);
+    const [error, setError] = useState<string>();
+
+    useEffect(() => {
+        setDisplayName(device.display_name);
+    }, [device.device_id, device.display_name]);
+
+    const onRename = () => {
+        setEditedName(displayName ?? '');
+        setError(undefined);
+        setIsEditing(true);
+    };
+
+    const onCancel = () => {
+        setError(undefined);
+        setIsEditing(false);
+    };
+
+    const onSave = async () => {
+        if (isSaving) return;
+        if (editedName === displayName) {
+            setIsEditing(false);
+            return;
+        }
+
+        setIsSaving(true);
+        setError(undefined);
+        try {
+            await saveDeviceName(device.device_id, editedName);
+            setDisplayName(editedName);
+            setIsEditing(false);
+        } catch (e) {
+            setError('Failed to set display name.');
+        } finally {
+            setIsSaving(false);
+        }
+    };
+
+    if (!isEditing) {
+        return <div className='mx_DeviceDetailHeading' data-testid='device-detail-heading'>
+            <Heading size='h3' data-testid='device-name-read'>{ displayName ?? device.device_id }</Heading>
+            <AccessibleButton kind='link_inline' onClick={onRename} data-testid='device-name-rename'>
+                { _t('Rename') }
+            </AccessibleButton>
+        </div>;
+    }
+
+    return <form className='mx_DeviceDetailHeading'
+        data-testid='device-name-edit'
+        onSubmit={(event) => {
+            event.preventDefault();
+            void onSave();
+        }}>
+        <Field
+            label={_t('Session name')}
+            value={editedName}
+            maxLength={100}
+            autoFocus
+            autoComplete='off'
+            onChange={(event: React.ChangeEvent<HTMLInputElement>) => setEditedName(event.target.value)}
+            data-testid='device-name-input'
+            disabled={isSaving}
+        />
+        <p>{ _t('Session names may be visible to people you communicate with.') }</p>
+        { error && <p role='alert' data-testid='device-name-error'>{ error }</p> }
+        <AccessibleButton element='button'
+            type='button'
+            kind='primary_sm'
+            disabled={isSaving}
+            onClick={() => void onSave()}
+            data-testid='device-name-save'>
+            { _t('Save') }
+        </AccessibleButton>
+        <AccessibleButton element='button'
+            type='button'
+            kind='link_inline'
+            disabled={isSaving}
+            onClick={onCancel}
+            data-testid='device-name-cancel'>
+            { _t('Cancel') }
+        </AccessibleButton>
+        { isSaving && <span data-testid='device-name-saving'><Spinner w={16} h={16} /></span> }
+    </form>;
+};
